 public static void main(String[] args){String secret="0123456789abcdef0123456789abcdef";String raw="tg://proxy?server=EXAMPLE.com&port=443&secret="+secret+"\nhttps://t.me/proxy?secret="+secret+"&server=example.com&port=443\nhttps://t.me/webproxy?server=site.dynv6.net&secret="+secret+"\ntg://proxy?server=bad&port=99999&secret="+secret+"\nhttps://evil.example/proxy?server=evil&port=443&secret="+secret;List<ManualEntry> parsed=ManualEntry.parse(raw);if(parsed.size()!=2||parsed.get(0).web||!parsed.get(1).web||parsed.get(1).port!=443)throw new AssertionError("Parse, canonical dedup, web or invalid port");if(!ManualEntry.parse("not a proxy").isEmpty())throw new AssertionError("Invalid input");if(UpdateVersion.newer(14,14)||UpdateVersion.newer(14,13)||!UpdateVersion.newer(14,15)||UpdateVersion.newer(0,15))throw new AssertionError("Version comparison");if(UpdateVersion.shouldCheck(false,false)||!UpdateVersion.shouldCheck(false,true)||!UpdateVersion.shouldCheck(true,false)||!UpdateVersion.shouldCheck(true,true))throw new AssertionError("Automatic versus manual update policy");System.out.println("PASS: personal proxy parsing, normalization/dedup, MTProto/WEB validation and update comparisons");}
